{
  "$defs": {
    "AttentionDirectiveIn": {
      "additionalProperties": false,
      "description": "Wire form of [`AttentionDirective`].",
      "properties": {
        "at": {
          "description": "Filled in by the authority.",
          "format": "int64",
          "type": [
            "integer",
            "null"
          ]
        },
        "from": {
          "description": "Filled in by the authority; ignored if sent.",
          "type": [
            "string",
            "null"
          ]
        },
        "id": {
          "description": "Id; assigned if absent.",
          "type": [
            "string",
            "null"
          ]
        },
        "steps": {
          "description": "Steps, in the order to show them.",
          "items": {
            "$ref": "#/$defs/AttentionStepIn"
          },
          "type": "array"
        },
        "to": {
          "description": "Principal who should look.",
          "type": "string"
        }
      },
      "required": [
        "to",
        "steps"
      ],
      "type": "object"
    },
    "AttentionStepIn": {
      "additionalProperties": false,
      "description": "Wire form of [`AttentionStep`].",
      "properties": {
        "say": {
          "description": "Optional short caption.",
          "type": [
            "string",
            "null"
          ]
        },
        "target": {
          "$ref": "#/$defs/TargetIn",
          "description": "What to look at."
        }
      },
      "required": [
        "target"
      ],
      "type": "object"
    },
    "Audience": {
      "additionalProperties": false,
      "description": "A person's capsule preferences (simple fields in the document, R3).",
      "properties": {
        "group": {
          "$ref": "#/$defs/UserGroup",
          "description": "User group."
        },
        "positions": {
          "additionalProperties": {
            "format": "double",
            "type": "number"
          },
          "description": "Positions: symbol → signed quantity (sign = long/short).",
          "type": "object"
        },
        "sensitivity": {
          "anyOf": [
            {
              "$ref": "#/$defs/Sensitivity"
            },
            {
              "type": "null"
            }
          ],
          "description": "Chosen sensitivity; absent = the group's default. The system never changes it."
        },
        "watchlist": {
          "description": "Watch list (symbols).",
          "items": {
            "type": "string"
          },
          "type": "array"
        }
      },
      "required": [
        "group"
      ],
      "type": "object"
    },
    "Bar": {
      "additionalProperties": false,
      "description": "One OHLCV bar.",
      "properties": {
        "c": {
          "description": "Close price.",
          "format": "double",
          "type": "number"
        },
        "h": {
          "description": "High price.",
          "format": "double",
          "type": "number"
        },
        "l": {
          "description": "Low price.",
          "format": "double",
          "type": "number"
        },
        "o": {
          "description": "Open price.",
          "format": "double",
          "type": "number"
        },
        "t": {
          "description": "Bar open time, epoch milliseconds UTC.",
          "format": "int64",
          "type": "integer"
        },
        "v": {
          "description": "Volume.",
          "format": "double",
          "type": "number"
        }
      },
      "required": [
        "t",
        "o",
        "h",
        "l",
        "c",
        "v"
      ],
      "type": "object"
    },
    "CapsuleState": {
      "description": "Lifecycle state of a capsule:\n`draft -> live -> (updated)* -> invalidated | expired | approved | rejected`.",
      "oneOf": [
        {
          "const": "draft",
          "description": "Not yet shown as live.",
          "type": "string"
        },
        {
          "const": "live",
          "description": "Updates itself as its series change.",
          "type": "string"
        },
        {
          "const": "invalidated",
          "description": "The invalidation condition happened.",
          "type": "string"
        },
        {
          "const": "expired",
          "description": "Validity window elapsed.",
          "type": "string"
        },
        {
          "const": "approved",
          "description": "A person approved it.",
          "type": "string"
        },
        {
          "const": "rejected",
          "description": "A person rejected it.",
          "type": "string"
        }
      ]
    },
    "ClaimRef": {
      "description": "What a claim is about.",
      "oneOf": [
        {
          "additionalProperties": false,
          "description": "A condition subscription of the receiving connection became true.",
          "properties": {
            "kind": {
              "const": "condition",
              "type": "string"
            },
            "sub": {
              "description": "The subscription id.",
              "type": "string"
            }
          },
          "required": [
            "kind",
            "sub"
          ],
          "type": "object"
        },
        {
          "additionalProperties": false,
          "description": "An intent's trigger became true.",
          "properties": {
            "intent": {
              "description": "Intent id.",
              "type": "string"
            },
            "kind": {
              "const": "intent",
              "type": "string"
            }
          },
          "required": [
            "kind",
            "intent"
          ],
          "type": "object"
        },
        {
          "additionalProperties": false,
          "description": "A live capsule's invalidation held (the capsule was invalidated).",
          "properties": {
            "capsule": {
              "description": "Capsule id.",
              "type": "string"
            },
            "finding": {
              "description": "Its finding.",
              "type": "string"
            },
            "kind": {
              "const": "capsule",
              "type": "string"
            }
          },
          "required": [
            "kind",
            "capsule",
            "finding"
          ],
          "type": "object"
        }
      ]
    },
    "Cmp": {
      "description": "Comparison in a colour condition.",
      "oneOf": [
        {
          "const": "lt",
          "description": "`<`",
          "type": "string"
        },
        {
          "const": "le",
          "description": "`<=`",
          "type": "string"
        },
        {
          "const": "gt",
          "description": "`>`",
          "type": "string"
        },
        {
          "const": "ge",
          "description": "`>=`",
          "type": "string"
        }
      ]
    },
    "Collection": {
      "description": "Item collections of a document.",
      "oneOf": [
        {
          "const": "series",
          "description": "Series.",
          "type": "string"
        },
        {
          "const": "views",
          "description": "Views.",
          "type": "string"
        },
        {
          "const": "facts",
          "description": "Facts.",
          "type": "string"
        },
        {
          "const": "findings",
          "description": "Findings.",
          "type": "string"
        },
        {
          "const": "capsules",
          "description": "Capsules.",
          "type": "string"
        },
        {
          "const": "intents",
          "description": "Intents.",
          "type": "string"
        },
        {
          "const": "narratives",
          "description": "Narratives.",
          "type": "string"
        },
        {
          "const": "proposals",
          "description": "Proposals.",
          "type": "string"
        }
      ]
    },
    "ColorSpec": {
      "anyOf": [
        {
          "description": "One colour.",
          "type": "string"
        },
        {
          "$ref": "#/$defs/ColorWhen",
          "description": "Colour by condition."
        },
        {
          "$ref": "#/$defs/ColorSteps",
          "description": "Colour by value steps."
        }
      ],
      "description": "The colour channel: constant, conditional or bound to a value.\n\nA colour is `#rrggbb`, `#rrggbbaa` or a theme token (`up`, `down`, `accent`, `text`,\n`muted`, `warn`, `s1`…`s8`; see `docs/GRAMMAR.md` §Tema)."
    },
    "ColorSpecIn": {
      "anyOf": [
        {
          "description": "One colour.",
          "type": "string"
        },
        {
          "$ref": "#/$defs/ColorWhenIn",
          "description": "Colour by condition."
        },
        {
          "$ref": "#/$defs/ColorSteps",
          "description": "Colour by value steps."
        }
      ],
      "description": "Wire form of [`crate::grammar::ColorSpec`]."
    },
    "ColorSteps": {
      "additionalProperties": false,
      "description": "Colour chosen per bar by the value of a field, in steps:\n`colors[i]` for `thresholds[i-1] <= value < thresholds[i]`.",
      "properties": {
        "colors": {
          "description": "`thresholds.len() + 1` colours.",
          "items": {
            "type": "string"
          },
          "type": "array"
        },
        "field": {
          "description": "Field of the layer's data.",
          "type": "string"
        },
        "thresholds": {
          "description": "Ascending thresholds (each needs an [`Origin`]).",
          "items": {
            "format": "double",
            "type": "number"
          },
          "type": "array"
        }
      },
      "required": [
        "field",
        "thresholds",
        "colors"
      ],
      "type": "object"
    },
    "ColorWhen": {
      "additionalProperties": false,
      "description": "Colour chosen per bar by a condition.",
      "properties": {
        "else": {
          "description": "Colour where it does not (and where a side is `null`).",
          "type": "string"
        },
        "then": {
          "description": "Colour where it holds.",
          "type": "string"
        },
        "when": {
          "$ref": "#/$defs/Predicate",
          "description": "The condition."
        }
      },
      "required": [
        "when",
        "then",
        "else"
      ],
      "type": "object"
    },
    "ColorWhenIn": {
      "additionalProperties": false,
      "description": "Wire form of [`crate::grammar::ColorWhen`].",
      "properties": {
        "else": {
          "description": "Colour where it does not.",
          "type": "string"
        },
        "then": {
          "description": "Colour where it holds.",
          "type": "string"
        },
        "when": {
          "$ref": "#/$defs/PredicateIn",
          "description": "The condition."
        }
      },
      "required": [
        "when",
        "then",
        "else"
      ],
      "type": "object"
    },
    "CompareOp": {
      "description": "Comparison operator used in conditions.",
      "oneOf": [
        {
          "const": "lt",
          "description": "Strictly less than.",
          "type": "string"
        },
        {
          "const": "le",
          "description": "Less than or equal.",
          "type": "string"
        },
        {
          "const": "gt",
          "description": "Strictly greater than.",
          "type": "string"
        },
        {
          "const": "ge",
          "description": "Greater than or equal.",
          "type": "string"
        },
        {
          "const": "cross_above",
          "description": "Crosses the value upwards.",
          "type": "string"
        },
        {
          "const": "cross_below",
          "description": "Crosses the value downwards.",
          "type": "string"
        }
      ]
    },
    "ConditionIn": {
      "description": "Wire form of [`Condition`]: series fields also take selectors.",
      "oneOf": [
        {
          "additionalProperties": false,
          "description": "Last value of a series compared against a constant.",
          "properties": {
            "kind": {
              "const": "threshold",
              "type": "string"
            },
            "op": {
              "$ref": "#/$defs/CompareOp",
              "description": "Comparison."
            },
            "series": {
              "$ref": "#/$defs/SeriesRef",
              "description": "Series id or selector."
            },
            "value": {
              "description": "Constant to compare against.",
              "format": "double",
              "type": "number"
            }
          },
          "required": [
            "kind",
            "series",
            "op",
            "value"
          ],
          "type": "object"
        },
        {
          "additionalProperties": false,
          "description": "One series compared against another.",
          "properties": {
            "kind": {
              "const": "compare",
              "type": "string"
            },
            "left": {
              "$ref": "#/$defs/SeriesRef",
              "description": "Left series id or selector."
            },
            "op": {
              "$ref": "#/$defs/CompareOp",
              "description": "Comparison."
            },
            "right": {
              "$ref": "#/$defs/SeriesRef",
              "description": "Right series id or selector."
            }
          },
          "required": [
            "kind",
            "left",
            "op",
            "right"
          ],
          "type": "object"
        },
        {
          "additionalProperties": false,
          "description": "Free text; evaluated by a person.",
          "properties": {
            "kind": {
              "const": "text",
              "type": "string"
            },
            "text": {
              "description": "Condition statement.",
              "type": "string"
            }
          },
          "required": [
            "kind",
            "text"
          ],
          "type": "object"
        }
      ]
    },
    "DataRef": {
      "additionalProperties": false,
      "description": "A reference to a field of a series: `{\"series\": \"sma50\", \"field\": \"sma\"}`. Within a\nlayer, `series` may be omitted (the layer's own data); `field` may be omitted for the\nseries' main output (`c` for bars).",
      "properties": {
        "field": {
          "description": "Field name: a bar field (`o`, `h`, `l`, `c`, `v`), a study output (`rsi`,\n`upper`, `histogram`...), `v` for a point series, or a fact/finding field.",
          "type": [
            "string",
            "null"
          ]
        },
        "series": {
          "description": "Series id; the layer's own series when absent.",
          "type": [
            "string",
            "null"
          ]
        }
      },
      "type": "object"
    },
    "DataRefIn": {
      "additionalProperties": false,
      "description": "Wire form of [`crate::grammar::DataRef`].",
      "properties": {
        "field": {
          "description": "Field name.",
          "type": [
            "string",
            "null"
          ]
        },
        "series": {
          "anyOf": [
            {
              "$ref": "#/$defs/SeriesRef"
            },
            {
              "type": "null"
            }
          ],
          "description": "Series id or selector; the layer's own series when absent."
        }
      },
      "type": "object"
    },
    "Depth": {
      "description": "Semantic zoom level: 0 sentence, 1 capsule, 2 marked chart, 3 full workspace.",
      "oneOf": [
        {
          "const": "sentence",
          "description": "Depth 0: one sentence.",
          "type": "string"
        },
        {
          "const": "capsule",
          "description": "Depth 1: the capsule.",
          "type": "string"
        },
        {
          "const": "chart",
          "description": "Depth 2: chart with marks.",
          "type": "string"
        },
        {
          "const": "workspace",
          "description": "Depth 3: full workspace.",
          "type": "string"
        }
      ]
    },
    "Emphasis": {
      "additionalProperties": false,
      "description": "A persistent emphasis on part of a view (a finding, a layer, a bar range). Attention\ndirectives and narration steps use the same target and are drawn the same way, but\nthey are presence, not document.",
      "properties": {
        "kind": {
          "$ref": "#/$defs/EmphasisKind",
          "description": "How."
        },
        "target": {
          "$ref": "#/$defs/Target",
          "description": "What is emphasised. `item` (a fact or finding) resolves to its bars."
        }
      },
      "required": [
        "target",
        "kind"
      ],
      "type": "object"
    },
    "EmphasisIn": {
      "additionalProperties": false,
      "description": "Wire form of [`crate::grammar::Emphasis`].",
      "properties": {
        "kind": {
          "$ref": "#/$defs/EmphasisKind",
          "description": "How."
        },
        "target": {
          "$ref": "#/$defs/TargetIn",
          "description": "What is emphasised."
        }
      },
      "required": [
        "target",
        "kind"
      ],
      "type": "object"
    },
    "EmphasisKind": {
      "description": "How an emphasis changes the drawing.",
      "oneOf": [
        {
          "const": "highlight",
          "description": "Mark the target (accent band behind its bars, thicker stroke for its layer).",
          "type": "string"
        },
        {
          "const": "focus",
          "description": "Dim everything except the target.",
          "type": "string"
        },
        {
          "const": "dim",
          "description": "Dim the target.",
          "type": "string"
        }
      ]
    },
    "Encoding": {
      "additionalProperties": false,
      "description": "The closed set of encoding channels. Unknown channel names are rejected\n(`schema`, with `did_you_mean`).",
      "properties": {
        "color": {
          "anyOf": [
            {
              "$ref": "#/$defs/ColorSpec"
            },
            {
              "type": "null"
            }
          ],
          "description": "Colour (stroke for lines and rules, fill for areas, bands, bars and points)."
        },
        "opacity": {
          "description": "Opacity `0..=1` (multiplies the colour's alpha).",
          "format": "double",
          "type": [
            "number",
            "null"
          ]
        },
        "size": {
          "anyOf": [
            {
              "$ref": "#/$defs/SizeSpec"
            },
            {
              "type": "null"
            }
          ],
          "description": "Size in pixels (point diameter, text size)."
        },
        "text": {
          "description": "Text of a `text` mark: a field of the layer's data (`text` of a fact, `claim` of a\nfinding).",
          "type": [
            "string",
            "null"
          ]
        },
        "width": {
          "description": "Stroke width in pixels (lines, rules, band edges).",
          "format": "double",
          "type": [
            "number",
            "null"
          ]
        },
        "x": {
          "anyOf": [
            {
              "$ref": "#/$defs/Position"
            },
            {
              "type": "null"
            }
          ],
          "description": "Horizontal position. Default: the row's bar. A constant makes a vertical rule."
        },
        "x2": {
          "anyOf": [
            {
              "$ref": "#/$defs/Position"
            },
            {
              "type": "null"
            }
          ],
          "description": "Second horizontal position (R3): the last bar of a bar extent. With `x`, a\nhorizontal `rule` becomes a segment from bar `x` to bar `x2` (sloped when `y2` is\nalso given), and a `band`/`area` covers only bars `x..=x2` (evidence geometry,\n`docs/GRAMMAR.md` §18)."
        },
        "y": {
          "anyOf": [
            {
              "$ref": "#/$defs/Position"
            },
            {
              "type": "null"
            }
          ],
          "description": "Vertical position. Default: the main output of the layer's series (`c` for bars,\n`v` for points, `level` for facts); for `line` on a multi-output study, one line\nper default output."
        },
        "y2": {
          "anyOf": [
            {
              "$ref": "#/$defs/Position"
            },
            {
              "type": "null"
            }
          ],
          "description": "Second vertical position: the lower edge of `band`/`area`, the base of `bar`."
        }
      },
      "type": "object"
    },
    "EncodingIn": {
      "additionalProperties": false,
      "description": "Wire form of [`crate::grammar::Encoding`]: series references inside channels also\ntake selectors.",
      "properties": {
        "color": {
          "anyOf": [
            {
              "$ref": "#/$defs/ColorSpecIn"
            },
            {
              "type": "null"
            }
          ],
          "description": "Colour."
        },
        "opacity": {
          "description": "Opacity `0..=1`.",
          "format": "double",
          "type": [
            "number",
            "null"
          ]
        },
        "size": {
          "anyOf": [
            {
              "$ref": "#/$defs/SizeSpec"
            },
            {
              "type": "null"
            }
          ],
          "description": "Size in pixels."
        },
        "text": {
          "description": "Text field of a `text` mark.",
          "type": [
            "string",
            "null"
          ]
        },
        "width": {
          "description": "Stroke width in pixels.",
          "format": "double",
          "type": [
            "number",
            "null"
          ]
        },
        "x": {
          "anyOf": [
            {
              "$ref": "#/$defs/PositionIn"
            },
            {
              "type": "null"
            }
          ],
          "description": "Horizontal position."
        },
        "x2": {
          "anyOf": [
            {
              "$ref": "#/$defs/PositionIn"
            },
            {
              "type": "null"
            }
          ],
          "description": "Second horizontal position (R3: last bar of an extent)."
        },
        "y": {
          "anyOf": [
            {
              "$ref": "#/$defs/PositionIn"
            },
            {
              "type": "null"
            }
          ],
          "description": "Vertical position."
        },
        "y2": {
          "anyOf": [
            {
              "$ref": "#/$defs/PositionIn"
            },
            {
              "type": "null"
            }
          ],
          "description": "Second vertical position."
        }
      },
      "type": "object"
    },
    "EvidenceValue": {
      "additionalProperties": false,
      "description": "One operand value a claim rests on: the main output of a series the condition reads,\nat the claim's bar and at the bar before it (`null` in warmup).",
      "properties": {
        "prev": {
          "description": "Value at the bar before `t` (absent as `value`).",
          "format": "double",
          "type": [
            "number",
            "null"
          ]
        },
        "series": {
          "description": "Series id (as in the condition).",
          "type": "string"
        },
        "t": {
          "description": "Bar time of `value` (the claim's bar on that series' bar series).",
          "format": "int64",
          "type": "integer"
        },
        "value": {
          "description": "Value at `t` (absent in warmup, and for a recipient without the data entitlement\nof the feed it rests on: §18.3, §19.7).",
          "format": "double",
          "type": [
            "number",
            "null"
          ]
        }
      },
      "required": [
        "series",
        "t"
      ],
      "type": "object"
    },
    "FactRef": {
      "anyOf": [
        {
          "description": "Fact id.",
          "type": "string"
        },
        {
          "$ref": "#/$defs/FactSel",
          "description": "Selector."
        }
      ],
      "description": "A fact id or a [`FactSel`]."
    },
    "FactSel": {
      "additionalProperties": false,
      "description": "Selects a fact, e.g. `{\"kind\":\"breakout\",\"latest\":true}`.",
      "properties": {
        "bar": {
          "description": "Bar index.",
          "format": "uint64",
          "minimum": 0,
          "type": [
            "integer",
            "null"
          ]
        },
        "first": {
          "description": "Pick the first match (by bar: the oldest).",
          "type": "boolean"
        },
        "kind": {
          "description": "Fact kind, exact (`cross_above`, `breakout`...).",
          "type": [
            "string",
            "null"
          ]
        },
        "latest": {
          "description": "Pick the last match (by bar: the most recent).",
          "type": "boolean"
        },
        "on": {
          "anyOf": [
            {
              "$ref": "#/$defs/SeriesRef"
            },
            {
              "type": "null"
            }
          ],
          "description": "The fact is about this series."
        }
      },
      "type": "object"
    },
    "FindingRef": {
      "anyOf": [
        {
          "description": "Finding id.",
          "type": "string"
        },
        {
          "$ref": "#/$defs/FindingSel",
          "description": "Selector."
        }
      ],
      "description": "A finding id or a [`FindingSel`]."
    },
    "FindingSel": {
      "additionalProperties": false,
      "description": "Selects a finding, e.g. `{\"kind\":\"breakout\",\"latest\":true}` (\"the latest breakout\").",
      "properties": {
